// CareerConnect App - Main Application Logic
class CareerConnect {
  constructor() {
    this.currentPage = 'home';
    this.savedJobs = this.loadSavedJobs();
    this.init();
  }

  init() {
    this.setupNavigation();
    this.setupTheme();
    this.setupEventListeners();
    this.handleRouting();
    window.addEventListener('hashchange', () => this.handleRouting());
  }

  setupNavigation() {
    const navToggle = document.querySelector('[data-nav-toggle]');
    const navMenu = document.querySelector('[data-nav-menu]');
    const navLinks = document.querySelectorAll('[data-nav-link]');

    if (navToggle) {
      navToggle.addEventListener('click', () => {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        navToggle.setAttribute('aria-expanded', !isExpanded);
        navMenu.classList.toggle('active');
      });
    }

    navLinks.forEach(link => {
      link.addEventListener('click', () => {
        navToggle?.setAttribute('aria-expanded', 'false');
        navMenu?.classList.remove('active');
      });
    });
  }

  setupTheme() {
    const themeToggle = document.querySelector('[data-theme-toggle]');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const savedTheme = localStorage.getItem('theme') || (prefersDark ? 'dark' : 'light');

    this.setTheme(savedTheme);

    if (themeToggle) {
      themeToggle.addEventListener('click', () => {
        const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
        const newTheme = currentTheme === 'light' ? 'dark' : 'light';
        this.setTheme(newTheme);
      });
    }
  }

  setTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }

  setupEventListeners() {
    const main = document.querySelector('main');
    if (main) {
      main.addEventListener('click', e => {
        if (e.target.matches('[data-save-job]')) {
          this.toggleSaveJob(e.target);
        }
      });
    }
  }

  handleRouting() {
    const hash = window.location.hash.slice(1) || 'home';
    this.currentPage = hash.split('?')[0];
    this.renderPage(this.currentPage);
  }

  renderPage(page) {
    const main = document.querySelector('main');
    if (!main) return;

    const pages = {
      home: this.renderHome.bind(this),
      jobs: this.renderJobs.bind(this),
      companies: this.renderCompanies.bind(this),
      saved: this.renderSaved.bind(this),
      news: this.renderNews.bind(this),
      about: this.renderAbout.bind(this),
      contact: this.renderContact.bind(this),
    };

    const render = pages[page] || pages.home;
    main.innerHTML = render();
    main.classList.add('slide-up');
  }

  renderHome() {
    return `
      <section class="hero">
        <h1>Welcome to CareerConnect</h1>
        <p>Discover vetted jobs, compare employers, and advance your career</p>
        <div class="cta-buttons">
          <a href="#jobs" class="btn btn-primary">Browse Jobs</a>
          <a href="#companies" class="btn btn-secondary">Explore Companies</a>
        </div>
      </section>
      <section class="features">
        <h2>Why Choose CareerConnect?</h2>
        <div class="feature-grid">
          <article class="feature-card">
            <h3>Vetted Opportunities</h3>
            <p>All positions are verified for authenticity and quality standards.</p>
          </article>
          <article class="feature-card">
            <h3>Easy Comparisons</h3>
            <p>Compare company benefits, culture, and growth opportunities side-by-side.</p>
          </article>
          <article class="feature-card">
            <h3>Saved Jobs</h3>
            <p>Save your favorite roles and revisit them anytime from your dashboard.</p>
          </article>
          <article class="feature-card">
            <h3>Fast Applications</h3>
            <p>Apply to positions with just a few clicks using your profile.</p>
          </article>
        </div>
      </section>
    `;
  }

  renderJobs() {
    return `
      <section class="jobs-section">
        <h1>Browse Jobs</h1>
        <p>Find the perfect role for your next career move.</p>
        <div class="jobs-container">
          <article class="job-card">
            <h3>Senior Frontend Engineer</h3>
            <p class="company">Tech Innovations Inc</p>
            <p class="location">Remote</p>
            <p class="salary">$120k - $150k</p>
            <button class="btn-save" data-save-job>Save Job</button>
          </article>
          <article class="job-card">
            <h3>Product Manager</h3>
            <p class="company">Creative Solutions</p>
            <p class="location">New York, NY</p>
            <p class="salary">$110k - $140k</p>
            <button class="btn-save" data-save-job>Save Job</button>
          </article>
          <article class="job-card">
            <h3>UX Designer</h3>
            <p class="company">Design Studio</p>
            <p class="location">San Francisco, CA</p>
            <p class="salary">$100k - $130k</p>
            <button class="btn-save" data-save-job>Save Job</button>
          </article>
        </div>
      </section>
    `;
  }

  renderCompanies() {
    return `
      <section class="companies-section">
        <h1>Explore Companies</h1>
        <p>Learn about top employers and their culture.</p>
        <div class="companies-container">
          <article class="company-card">
            <h3>Tech Innovations Inc</h3>
            <p>Building cutting-edge technology solutions</p>
            <p class="rating">Rating: ⭐ 4.8/5</p>
          </article>
          <article class="company-card">
            <h3>Creative Solutions</h3>
            <p>Design-focused product development</p>
            <p class="rating">Rating: ⭐ 4.6/5</p>
          </article>
          <article class="company-card">
            <h3>Design Studio</h3>
            <p>Excellence in digital design</p>
            <p class="rating">Rating: ⭐ 4.7/5</p>
          </article>
        </div>
      </section>
    `;
  }

  renderSaved() {
    const jobs = this.savedJobs.length > 0
      ? this.savedJobs.map(job => `
          <article class="saved-job-card">
            <h3>${job.title}</h3>
            <p class="company">${job.company}</p>
            <p class="location">${job.location}</p>
            <button class="btn-remove" data-remove-job="${job.id}">Remove</button>
          </article>
        `).join('')
      : '<p>No saved jobs yet. <a href="#jobs">Browse jobs</a></p>';

    return `
      <section class="saved-section">
        <h1>Saved Jobs</h1>
        <p>Your collection of favorite opportunities</p>
        <div class="saved-container">
          ${jobs}
        </div>
      </section>
    `;
  }

  renderNews() {
    return `
      <section class="news-section">
        <h1>Hiring News</h1>
        <p>Stay updated with the latest recruitment trends.</p>
        <div class="news-container">
          <article class="news-card">
            <h3>Remote Work Trends 2026</h3>
            <p>How companies are adapting to hybrid work models.</p>
            <time>July 24, 2026</time>
          </article>
          <article class="news-card">
            <h3>Skills in Demand</h3>
            <p>The top 10 skills employers are looking for this year.</p>
            <time>July 20, 2026</time>
          </article>
          <article class="news-card">
            <h3>Interview Preparation Guide</h3>
            <p>Tips and strategies for acing your next interview.</p>
            <time>July 15, 2026</time>
          </article>
        </div>
      </section>
    `;
  }

  renderAbout() {
    return `
      <section class="about-section">
        <h1>About CareerConnect</h1>
        <p>CareerConnect is a modern recruitment platform dedicated to making job search and hiring more transparent and human-centered.</p>
        <h2>Our Mission</h2>
        <p>To connect talented professionals with opportunities that match their skills, values, and aspirations.</p>
        <h2>Our Values</h2>
        <ul>
          <li><strong>Transparency:</strong> Clear information about roles and companies</li>
          <li><strong>Quality:</strong> Vetted positions and reputable employers</li>
          <li><strong>Accessibility:</strong> Easy-to-use platform for everyone</li>
          <li><strong>Community:</strong> Supporting job seekers and employers alike</li>
        </ul>
      </section>
    `;
  }

  renderContact() {
    return `
      <section class="contact-section">
        <h1>Contact Us</h1>
        <p>Have questions or feedback? We'd love to hear from you.</p>
        <form class="contact-form" onsubmit="event.preventDefault(); alert('Thank you for your message!');">
          <div class="form-group">
            <label for="name">Name</label>
            <input type="text" id="name" required>
          </div>
          <div class="form-group">
            <label for="email">Email</label>
            <input type="email" id="email" required>
          </div>
          <div class="form-group">
            <label for="message">Message</label>
            <textarea id="message" rows="5" required></textarea>
          </div>
          <button type="submit" class="btn btn-primary">Send Message</button>
        </form>
      </section>
    `;
  }

  toggleSaveJob(button) {
    const jobTitle = button.closest('.job-card')?.querySelector('h3')?.textContent;
    if (!jobTitle) return;

    const isSaved = this.savedJobs.some(j => j.title === jobTitle);
    if (isSaved) {
      this.savedJobs = this.savedJobs.filter(j => j.title !== jobTitle);
      button.textContent = 'Save Job';
    } else {
      this.savedJobs.push({
        id: Date.now(),
        title: jobTitle,
        company: button.closest('.job-card')?.querySelector('.company')?.textContent || '',
        location: button.closest('.job-card')?.querySelector('.location')?.textContent || ''
      });
      button.textContent = '✓ Saved';
    }

    this.saveSavedJobs();
    this.updateSavedCount();
    this.showToast(isSaved ? 'Job removed from saved' : 'Job saved successfully!');
  }

  loadSavedJobs() {
    return JSON.parse(localStorage.getItem('savedJobs') || '[]');
  }

  saveSavedJobs() {
    localStorage.setItem('savedJobs', JSON.stringify(this.savedJobs));
  }

  updateSavedCount() {
    const counter = document.querySelector('[data-saved-count]');
    if (counter) {
      counter.textContent = this.savedJobs.length;
    }
  }

  showToast(message) {
    const toast = document.querySelector('[data-toast]');
    if (!toast) return;
    toast.textContent = message;
    toast.removeAttribute('hidden');
    setTimeout(() => toast.setAttribute('hidden', ''), 3000);
  }
}

// Initialize app when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => new CareerConnect());
} else {
  new CareerConnect();
}
